```php
<?php
/**
 * Optimized Authentication Module
 * Production-ready with security and performance improvements
 */

class Authentication {
    private $pdo;
    private $config;

    /**
     * Initialize authentication system
     * @param PDO $pdo Database connection
     */
    public function __construct(PDO $pdo) {
        $this->pdo = $pdo;
        $this->config = [
            'session_timeout' => 3600,
            'max_login_attempts' => 5,
            'lockout_time' => 900,
            'password_min_length' => 8,
            'csrf_token_length' => 32
        ];
    }

    /**
     * User login with validation
     * @param string $username
     * @param string $password
     * @return array Result with status and message
     */
    public function login(string $username, string $password): array {
        try {
            // Validate input
            if (!$this->validateCredentials($username, $password)) {
                return $this->errorResponse('Invalid credentials format');
            }

            // Check login attempts
            if ($this->isAccountLocked($username)) {
                return $this->errorResponse('Account temporarily locked');
            }

            // Get user data
            $user = $this->getUserByUsername($username);

            if (!$user || !$this->verifyPassword($password, $user['password_hash'])) {
                $this->logFailedAttempt($username);
                return $this->errorResponse('Invalid username or password');
            }

            // Check if account is active
            if (!$user['is_active']) {
                return $this->errorResponse('Account is disabled');
            }

            // Create session
            $this->createSession($user);

            // Clear failed attempts
            $this->clearFailedAttempts($username);

            // Log successful login
            $this->logAccess($user['id'], 'login');

            return $this->successResponse('Login successful', [
                'user_id' => $user['id'],
                'username' => $user['username'],
                'role' => $user['role']
            ]);

        } catch (Exception $e) {
            error_log("Login error: " . $e->getMessage());
            return $this->errorResponse('Authentication error occurred');
        }
    }

    /**
     * User registration
     * @param array $userData
     * @return array Result with status
     */
    public function register(array $userData): array {
        try {
            // Validate required fields
            $required = ['username', 'password', 'email'];
            foreach ($required as $field) {
                if (empty($userData[$field])) {
                    return $this->errorResponse("Missing required field: $field");
                }
            }

            // Check if user exists
            if ($this->userExists($userData['username'], $userData['email'])) {
                return $this->errorResponse('User already exists');
            }

            // Validate password strength
            if (!$this->validatePasswordStrength($userData['password'])) {
                return $this->errorResponse('Password does not meet requirements');
            }

            // Hash password
            $hashedPassword = $this->hashPassword($userData['password']);

            // Prepare user data
            $userData['password_hash'] = $hashedPassword;
            $userData['created_at'] = date('Y-m-d H:i:s');
            $userData['is_active'] = 1;

            // Insert user
            $userId = $this->insertUser($userData);

            if ($userId) {
                $this->logAccess($userId, 'registration');
                return $this->successResponse('Registration successful', ['user_id' => $userId]);
            }

            return $this->errorResponse('Registration failed');

        } catch (Exception $e) {
            error_log("Registration error: " . $e->getMessage());
            return $this->errorResponse('Registration error occurred');
        }
    }

    /**
     * Validate user credentials
     * @param string $username
     * @param string $password
     * @return bool
     */
    private function validateCredentials(string $username, string $password): bool {
        // Basic validation
        if (empty($username) || empty($password)) {
            return false;
        }

        // Username validation (alphanumeric, 3-20 chars)
        if (!preg_match('/^[a-zA-Z0-9_]{3,20}$/', $username)) {
            return false;
        }

        // Password length check
        if (strlen($password) < $this->config['password_min_length']) {
            return false;
        }

        return true;
    }

    /**
     * Check if account is locked due to failed attempts
     * @param string $username
     * @return bool
     */
    private function isAccountLocked(string $username): bool {
        $stmt = $this->pdo->prepare("
            SELECT COUNT(*) as attempts, MAX(attempt_time) as last_attempt 
            FROM failed_login_attempts 
            WHERE username = ? AND attempt_time > DATE_SUB(NOW(), INTERVAL ? SECOND)
        ");

        $stmt->execute([$username, $this->config['lockout_time']]);
        $result = $stmt->fetch(PDO::FETCH_ASSOC);

        return ($result['attempts'] >= $this->config['max_login_attempts']);
    }

    /**
     * Get user by username
     * @param string $username
     * @return array|null
     */
    private function getUserByUsername(string $username): ?array {
        $stmt = $this->pdo->prepare("
            SELECT id, username, password_hash, email, role, is_active 
            FROM users 
            WHERE username = ? OR email = ?
        ");

        $stmt->execute([$username, $username]);
        $user = $stmt->fetch(PDO::FETCH_ASSOC);

        return $user ?: null;
    }

    /**
     * Verify password against hash
     * @param string $password
     * @param string $hash
     * @return bool
     */
    private function verifyPassword(string $password, string $hash): bool {
        return password_verify($password, $hash);
    }

    /**
     * Hash password using bcrypt
     * @param string $password
     * @return string
     */
    private function hashPassword(string $password): string {
        return password_hash($password, PASSWORD_BCRYPT, ['cost' => 12]);
    }

    /**
     * Create user session
     * @param array $user
     */
    private function createSession(array $user): void {
        session_start([
            'cookie_lifetime' => $this->config['session_timeout'],
            'use_strict_mode' => true,
            'use_cookies' => true,
            'use_only_cookies' => true,
            'cookie_httponly' => true,
            'cookie_secure' => isset($_SERVER['HTTPS']),
        ]);

        // Regenerate session ID to prevent fixation
        session_regenerate_id(true);

        $_SESSION['user_id'] = $user['id'];
        $_SESSION['username'] = $user['username'];
        $_SESSION['role'] = $user['role'];
        $_SESSION['login_time'] = time();
        $_SESSION['csrf_token'] = bin2hex(random_bytes($this->config['csrf_token_length']));
    }

    /**
     * Log failed login attempt
     * @param string $username
     */
    private function logFailedAttempt(string $username): void {
        $stmt = $this->pdo->prepare("
            INSERT INTO failed_login_attempts (username, ip_address, user_agent, attempt_time) 
            VALUES (?, ?, ?, NOW())
        ");

        $stmt->execute([
            $username,
            $_SERVER['REMOTE_ADDR'] ?? 'unknown',
            $_SERVER['HTTP_USER_AGENT'] ?? 'unknown'
        ]);
    }

    /**
     * Clear failed attempts on successful login
     * @param string $username
     */
    private function clearFailedAttempts(string $username): void {
        $stmt = $this->pdo->prepare("
            DELETE FROM failed_login_attempts WHERE username = ?
        ");
        $stmt->execute([$username]);
    }

    /**
     * Log user access
     * @param int $userId
     * @param string $action
     */
    private function logAccess(int $userId, string $action): void {
        $stmt = $this->pdo->prepare("
            INSERT INTO access_logs (user_id, action, ip_address, user_agent, timestamp) 
            VALUES (?, ?, ?, ?, NOW())
        ");

        $stmt->execute([
            $userId,
            $action,
            $_SERVER['REMOTE_ADDR'] ?? 'unknown',
            $_SERVER['HTTP_USER_AGENT'] ?? 'unknown'
        ]);
    }

    /**
     * Check if user exists
     * @param string $username
     * @param string $email
     * @return bool
     */
    private function userExists(string $username, string $email): bool {
        $stmt = $this->pdo->prepare("
            SELECT COUNT(*) as count FROM users WHERE username = ? OR email = ?
        ");

        $stmt->execute([$username, $email]);
        $result = $stmt->fetch(PDO::FETCH_ASSOC);

        return $result['count'] > 0;
    }

    /**
     * Validate password strength
     * @param string $password
     * @return bool
     */
    private function validatePasswordStrength(string $password): bool {
        if (strlen($password) < $this->config['password_min_length']) {
            return false;
        }

        // Check for at least one uppercase, one lowercase, one number
        if (!preg_match('/[A-Z]/', $password) ||
            !preg_match('/[a-z]/', $password) ||
            !preg_match('/[0-9]/', $password)) {
            return false;
        }

        return true;
    }

    /**
     * Insert new user
     * @param array $userData
     * @return int|null
     */
    private function insertUser(array $userData): ?int {
        $stmt = $this->pdo->prepare("
            INSERT INTO users (username, password_hash, email, role, is_active, created_at) 
            VALUES (?, ?, ?, 'user', ?, ?)
        ");

        $stmt->execute([
            $userData['username'],
            $userData['password_hash'],
            $userData['email'],
            $userData['is_active'],
            $userData['created_at']
        ]);

        return $this->pdo->lastInsertId() ?: null;
    }

    /**
     * Success response helper
     * @param string $message
     * @param array $data
     * @return array
     */
    private function successResponse(string $message, array $data = []): array {
        return [
            'success' => true,
            'message' => $message,
            'data' => $data,
            'timestamp' => time()
        ];
    }

    /**
     * Error response helper
     * @param string $message
     * @return array
     */
    private function errorResponse(string $message): array {
        return [
            'success' => false,
            'message' => $message,
            'timestamp' => time()
        ];
    }

    /**
     * Logout user
     * @return bool
     */
    public function logout(): bool {
        session_start();
        $_SESSION = [];

        if (ini_get("session.use_cookies")) {
            $params = session_get_cookie_params();
            setcookie(session_name(), '', time() - 42000,
                $params["path"], $params["domain"],
                $params["secure"], $params["httponly"]
            );
        }

        return session_destroy();
    }

    /**
     * Validate session
     * @return bool
     */
    public function validateSession(): bool {
        session_start();

        if (!isset($_SESSION['user_id'], $_SESSION['login_time'])) {
            return false;
        }

        // Check session timeout
        if (time() - $_SESSION['login_time'] > $this->config['session_timeout']) {
            $this->logout();
            return false;
        }

        // Update last activity time
        $_SESSION['login_time'] = time();

        return true;
    }
}

/**
 * Helper function to get CSRF token
 * @return string|null
 */
function getCsrfToken(): ?string {
    return $_SESSION['csrf_token'] ?? null;
}

/**
 * Helper function to validate CSRF token
 * @param string $token
 * @return bool
 */
function validateCsrfToken(string $token): bool {
    return isset($_SESSION['csrf_token']) && hash_equals($_SESSION['csrf_token'], $token);
}
